public static void BubbleSort(int[] array)
{
    for (int i = 0; i < array.Length - 1; i++) // 当前元素移动到下一个位置
    {
        for (int j = 0; j < array.Length - (i + 1); j++) // 交换已经按照顺序排列过的下标的元素
